#!/usr/bin/env python3
"""Generate the Objective-C/Metal runtime shim that lets Dawn's Metal objects, compiled by Cosmopolitan's clang as ELF, run inside a Cosmopolitan program on macOS arm64.
The objects contain no Mach-O metadata; what they need from outside is (measured with nm -u): the Objective-C message call, class references, selector references, constant
CFStrings, a few CoreFoundation / IOKit / IOSurface / Metal functions and constants, and the block class symbol. The shim defines every one of those symbols; at start-up
(dawn_cosmo_objc_init) it loads the system frameworks, points the trampolines at the real functions, and rewrites the three data sections.
usage: gen_objc_shim.py <undefined-symbols.txt> <outdir>   (one symbol per line)"""
import sys, os, re
syms = sorted({l.strip() for l in open(sys.argv[1]) if l.strip()})
out = sys.argv[2]; os.makedirs(out, exist_ok=True)
classes = [s for s in syms if s.startswith('OBJC_CLASS_$_')]
blocks = [s for s in syms if s.startswith('_NSConcrete')]
data = {'kCFAllocatorDefault': 8, 'kIOMainPortDefault': 8, 'MTLCommonCounterSetTimestamp': 8, 'MTLCommonCounterTimestamp': 8, 'kCFBooleanTrue': 8, 'kCFBooleanFalse': 8}
datas = [s for s in syms if s in data]
cfclass = [s for s in syms if s == '__CFConstantStringClassReference']
# Apple functions (everything else that is not C library / compiler support, which Cosmopolitan provides)
libc = {'__isPlatformVersionAtLeast', '__isOSVersionAtLeast', 'abort', 'ceilf', 'memchr', 'memcmp', 'memcpy', 'memmove', 'memset', 'setenv', 'strlen', 'memcpy', '__demangle', 'floorf', 'sqrtf', 'getenv'}
funcs = [s for s in syms if s not in classes and s not in blocks and s not in datas and s not in cfclass and s not in libc and not s.startswith(('_Z', '__cxa', '__gxx', '_Unwind'))]
funcs = [f for f in funcs if f != 'NSLog']   # variadic: replaced by a no-op below (Apple's arm64 variadic convention differs from the standard one)
lines = ['/* generated by gen_objc_shim.py - do not edit */', '#include <stdint.h>', '#include <stdbool.h>', '#include <string.h>', '#include <dlfcn.h>', '#include <cosmo.h>', '']
lines += ['void NSLog(void *format, ...) { (void)format; }', '']
lines += ['/* @available(macOS x, *) compiles to a call into the compiler runtime; the OS version is read once at start-up */',
          'static int dawn_cosmo_os[3] = {0, 0, 0};',
          'static int dawn_cosmo_at_least(int major, int minor, int sub) { if (dawn_cosmo_os[0] != major) return dawn_cosmo_os[0] > major; if (dawn_cosmo_os[1] != minor) return dawn_cosmo_os[1] > minor; return dawn_cosmo_os[2] >= sub; }',
          'int __isPlatformVersionAtLeast(uint32_t platform, uint32_t major, uint32_t minor, uint32_t sub) { (void)platform; return dawn_cosmo_at_least((int)major, (int)minor, (int)sub); }',
          'int __isOSVersionAtLeast(int major, int minor, int sub) { return dawn_cosmo_at_least(major, minor, sub); }', '']
lines += ['/* class references: the symbol is a C string holding the class name; the classrefs section is rewritten with the real class objects at start-up */']
for c in classes:
    n = c[len('OBJC_CLASS_$_'):]
    size = ((len(n) + 1 + 15) // 16) * 16
    lines.append(f'__attribute__((section("dawn_cosmo_classstubs"), aligned(16))) char dawn_cosmo_cls_{n}[{size}] __asm__("{c}") = "{n}";')
for b in blocks:
    lines.append(f'__attribute__((aligned(16))) char dawn_cosmo_block_{b.strip("_")}[64] __asm__("{b}");   /* only its address is stored as a block\'s isa; Block_copy does not look at it */')
for c in cfclass:
    lines.append(f'__attribute__((aligned(16))) char dawn_cosmo_cfstring_class[64] __asm__("{c}");   /* replaced by the real class in every cfstring literal at start-up */')
for d in datas:
    lines.append(f'uint64_t dawn_cosmo_data_{d} __asm__("{d}");')
lines += ['', '/* trampolines: each jumps through a pointer filled in at start-up. x16/x17 are the only registers used, so all argument registers and the link register are untouched. */']
for f in funcs:
    lines.append(f'void *dawn_cosmo_fn_{f};')
    lines.append(f'__asm__(".text\\n.globl {f}\\n.type {f},%function\\n{f}:\\n  adrp x16, dawn_cosmo_fn_{f}\\n  ldr x16, [x16, :lo12:dawn_cosmo_fn_{f}]\\n  br x16\\n");')
lines += ['', 'extern char __start_objc_selrefs[] __attribute__((weak)), __stop_objc_selrefs[] __attribute__((weak));',
          'extern char __start_objc_classrefs[] __attribute__((weak)), __stop_objc_classrefs[] __attribute__((weak));',
          'extern char __start_cfstring[] __attribute__((weak)), __stop_cfstring[] __attribute__((weak));',
          'extern char __start_dawn_cosmo_classstubs[] __attribute__((weak)), __stop_dawn_cosmo_classstubs[] __attribute__((weak));', '']
lines += ['static void *find(void **libs, int n, const char *name) { for (int i = 0; i < n; i++) if (libs[i]) { void *p = cosmo_dlsym(libs[i], name); if (p) return p; } return 0; }', '']
lines += ['/* returns true when Metal could be reached; false anywhere but macOS or when a framework or symbol is missing */', 'bool dawn_cosmo_objc_init(void) {', '  static int state;', '  if (state) return state > 0;', '  state = -1;', '  if (!IsXnu()) return false;']
lines += ['  const char *paths[] = {"/usr/lib/libobjc.A.dylib", "/usr/lib/libSystem.B.dylib", "/System/Library/Frameworks/Foundation.framework/Foundation", "/System/Library/Frameworks/CoreFoundation.framework/CoreFoundation",',
          '    "/System/Library/Frameworks/Metal.framework/Metal", "/System/Library/Frameworks/IOSurface.framework/IOSurface", "/System/Library/Frameworks/QuartzCore.framework/QuartzCore", "/System/Library/Frameworks/IOKit.framework/IOKit", "/System/Library/Frameworks/CoreVideo.framework/CoreVideo"};',
          '  void *libs[9]; for (int i = 0; i < 9; i++) libs[i] = cosmo_dlopen(paths[i], RTLD_NOW | RTLD_GLOBAL);',
          '  if (!libs[0] || !libs[2] || !libs[4]) return false;   /* libobjc, Foundation, Metal are required */',
          '  void *(*getClass)(const char *) = (void *(*)(const char *))find(libs, 9, "objc_getClass");',
          '  void *(*registerName)(const char *) = (void *(*)(const char *))find(libs, 9, "sel_registerName");',
          '  if (!getClass || !registerName) return false;',
          '  { int (*sysctlbyname_)(const char *, void *, size_t *, void *, size_t) = (int (*)(const char *, void *, size_t *, void *, size_t))find(libs, 9, "sysctlbyname");',
          '    char v[32] = ""; size_t n = sizeof v;',
          '    if (!sysctlbyname_ || sysctlbyname_("kern.osproductversion", v, &n, 0, 0) != 0) return false;',
          '    int part = 0; for (const char *c = v; *c && part < 3; c++) { if (*c == \'.\') part++; else if (*c >= \'0\' && *c <= \'9\') dawn_cosmo_os[part] = dawn_cosmo_os[part] * 10 + (*c - \'0\'); } }']
for f in funcs:
    lines.append(f'  if (!(dawn_cosmo_fn_{f} = find(libs, 9, "{f}"))) return false;')
for d in datas:
    sz = data[d]
    lines.append(f'  {{ void *p = find(libs, 9, "{d}"); if (!p) return false; memcpy(&dawn_cosmo_data_{d}, p, {sz}); }}')
lines += ['  /* selector references: slot holds a pointer to the selector name -> the registered selector */',
          '  for (uint64_t *s = (uint64_t *)__start_objc_selrefs; s < (uint64_t *)__stop_objc_selrefs; s++) *s = (uint64_t)registerName((const char *)*s);',
          '  /* class references: slot holds the address of one of the name stubs above -> the real class object */',
          '  for (uint64_t *s = (uint64_t *)__start_objc_classrefs; s < (uint64_t *)__stop_objc_classrefs; s++) {',
          '    if (*s >= (uint64_t)__start_dawn_cosmo_classstubs && *s < (uint64_t)__stop_dawn_cosmo_classstubs) { void *c = getClass((const char *)*s); if (!c) return false; *s = (uint64_t)c; }',
          '  }']
if cfclass:
    lines += ['  /* constant strings: {isa, flags, data, length} 32 bytes each; isa -> the real CFString class */',
              '  { void *cls = find(libs, 9, "__CFConstantStringClassReference"); if (!cls) return false;',
              '    for (uint64_t *s = (uint64_t *)__start_cfstring; s < (uint64_t *)__stop_cfstring; s += 4) s[0] = (uint64_t)cls; }']
lines += ['  state = 1;', '  return true;', '}']
open(os.path.join(out, 'objc_shim.c'), 'w').write('\n'.join(lines) + '\n')
print(f'{len(classes)} classes, {len(funcs)} functions, {len(datas)} data symbols, {len(blocks)} block symbols, cfstring={bool(cfclass)}')
print('functions:', ' '.join(funcs))
